# Коллажи v3 (отдельная регистрация; дизайн ПЛАН_КОЛЛАЖИ_v3.md v3.1): обучение на Kaggle. e_train_kaggle_c67.py (md5 8ac2057ff0dc3babfe8025fa745aaea0).
# Сессия гейта: зерно 0 условий 6 (упорядоченная пара) и 7 (неупорядоченная), по одному на каждой T4. Логи - /kaggle/working/e_full_c*_s*_log.txt
import zlib, base64, hashlib, subprocess, threading, time, os, glob
Z = ""
src = zlib.decompress(base64.b64decode(Z))
assert hashlib.md5(src).hexdigest() == "8ac2057ff0dc3babfe8025fa745aaea0", "код повреждён"
open("/kaggle/working/e_train_kaggle_c67.py", "wb").write(src)
DATA = "/kaggle/input/notebooks/yernazargabdrakhman/e-prep-in100/in100pack"
JOBS = {0: [(6, 0)], 1: [(7, 0)]}
RESUME = {}          # для следующих сессий: {(усл, зерно): "/kaggle/input/.../e_full/c1_s0"}
WORKERS, LIMIT_H, T0 = 2, 11.3, time.time()
print("md5 ok; данные:", os.path.exists(DATA + "/index.npz"), "; старт", time.strftime("%H:%M:%S", time.gmtime()), "UTC", flush=True)

def lane(gpu):
    for c, s in JOBS[gpu]:
        left = LIMIT_H - (time.time() - T0) / 3600
        if left < 0.6:
            print(f"GPU {gpu}: c{c}_s{s} не начато - мало времени ({left:.2f} ч)", flush=True)
            continue
        cmd = (f"cd /kaggle/working && python -u e_train_kaggle_c67.py --cond {c} --seed {s} --gpu {gpu} --workers {WORKERS} "
               f"--hours {left:.2f} --data {DATA}" + (f" --resume {RESUME[(c, s)]}" if (c, s) in RESUME else "")
               + f" 2>&1 | tee -a /kaggle/working/e_full_c{c}_s{s}_log.txt > /dev/null")
        t = time.time()
        r = subprocess.run("set -o pipefail; " + cmd, shell=True, executable="/bin/bash")
        print(f"GPU {gpu}: c{c}_s{s} код {r.returncode}, {(time.time() - t) / 3600:.2f} ч", flush=True)

th = [threading.Thread(target=lane, args=(g,)) for g in JOBS]
for x in th: x.start()
for x in th: x.join()
for f in sorted(glob.glob("/kaggle/working/e_full/c*_s*/*.pt")):
    print(f, hashlib.md5(open(f, "rb").read()).hexdigest(), flush=True)
for f in sorted(glob.glob("/kaggle/working/e_full_c*_log.txt")):
    print("== " + f); print("".join(l for l in open(f) if "закончена" in l or "Готово" in l or "СВЕРКА" in l or "⚠" in l or "Остановка" in l)[-3000:], flush=True)
